insert into doc_explainer (doc_type, name, what_it_is, why_it_matters, summary_fields, where_from, what_pba_checks, if_late) values
 ('bank', 'Bank statement', 'The bank''s own record of every rupee that went in and out of one account during the month.', 'It''s the only outside proof of your cash. We match your books to it line by line, so the cash and runway on your dashboard are real.', '[{"label": "Opening balance", "type": "amount"}, {"label": "Closing balance", "type": "amount"}, {"label": "Money in", "type": "amount"}, {"label": "Money out", "type": "amount"}]'::jsonb, 'Your bank''s net banking → Accounts → Statement → pick the month → download as PDF. One per account.', 'Opening balance matches last month''s closing. Every large payment has a bill behind it. Closing balance matches the books to the rupee.', 'Nothing can be checked without it — the whole month waits.'),
 ('sales', 'Sales invoice register', 'A list of every invoice the company raised in the month — who it went to, how much, and the GST on it.', 'Your revenue and your GST bill both start here. If an invoice is missing, revenue is understated and GST can be short-paid.', '[{"label": "Invoices raised", "type": "number"}, {"label": "Total billed (with GST)", "type": "amount"}, {"label": "GST charged", "type": "amount"}]'::jsonb, 'Export from Tally (Display → Account books → Sales register) or your billing tool, for the month.', 'Every invoice is in the GSTR-1. Totals match the revenue in the books. No invoice numbers are skipped.', 'Revenue and GST can''t be worked out, so GSTR-1 (due the 11th) is at risk.'),
 ('coll', 'Collections received', 'Money that actually arrived from customers this month — not what was invoiced, what was received.', 'Billing isn''t cash. This shows how much of what you billed turned into money in the bank.', '[{"label": "Amount collected", "type": "amount"}, {"label": "Clients who paid", "type": "number"}, {"label": "Largest receipt", "type": "amount"}]'::jsonb, 'From the bank statement, or your billing tool''s payments report. One line per receipt, with the client name.', 'Each receipt is matched to an invoice, so we know who still owes you.', 'Money-owed figures and collection days stay out of date.'),
 ('debt', 'Debtors ageing', 'Who owes the company money at month end, split by how long it has been due: 0–30, 31–60, 61–90 and over 90 days.', 'Money owed for over 90 days is the money least likely to come in. Catching it early protects your cash.', '[{"label": "Total owed to you", "type": "amount"}, {"label": "Of which over 90 days", "type": "amount"}, {"label": "Largest debtor", "type": "text"}]'::jsonb, 'Tally → Display → Statements of accounts → Outstandings → Receivables, with ageing.', 'Totals match the books; anything over 90 days is followed up.', 'Money-owed on the dashboard can''t be updated.'),
 ('pay', 'Payroll register', 'The month''s salary sheet — each person''s gross pay, deductions and what was actually paid.', 'Salaries are usually your largest cost. It also drives PF, ESI, professional tax and salary TDS — all of which carry penalties if wrong.', '[{"label": "People paid", "type": "number"}, {"label": "Gross salary", "type": "amount"}, {"label": "Net paid", "type": "amount"}, {"label": "TDS deducted", "type": "amount"}]'::jsonb, 'Your payroll sheet for the month — gross, deductions and net paid for each person.', 'Net pay matches what left the bank. Salary TDS, PF, ESI and professional tax are worked out from it.', 'Salary TDS (due the 7th) and PF (due the 15th) can''t be confirmed.'),
 ('contr', 'Contractor payments', 'Payments to consultants and contractors who are not on payroll.', 'They need TDS deducted and are a common audit question. Keeping them separate from salaries keeps both clean.', '[{"label": "Contractors paid", "type": "number"}, {"label": "Total paid", "type": "amount"}, {"label": "TDS deducted", "type": "amount"}]'::jsonb, 'A list of consultants paid this month, with invoice amounts and TDS cut.', 'TDS was cut at the right rate (usually 10%) and deposited.', 'TDS on vendors can''t be confirmed for the month.'),
 ('pt', 'Professional tax challan', 'Proof that professional tax — a small state tax on salaries — was paid.', 'It''s a state requirement. Late payment brings interest and penalties, and it''s checked at audit.', '[{"label": "Amount paid", "type": "amount"}, {"label": "Paid on", "type": "date"}]'::jsonb, 'The receipt from the state''s professional tax payment site, or from your bank.', 'Amount matches the number of people and the state''s slabs.', 'Interest and a penalty from the state.'),
 ('fr', 'Founder remuneration', 'What each founder is approved to draw as salary, against what they actually drew.', 'Investors and auditors look at this closely. Drawing above what''s approved needs board or shareholder approval.', '[{"label": "Approved for the quarter", "type": "amount"}, {"label": "Actually drawn", "type": "amount"}]'::jsonb, 'Board resolution and payroll for the founders.', 'What was drawn is within what was approved.', 'Investors and auditors will ask.'),
 ('partner', 'Amounts paid to partners', 'What the company paid or owes to revenue-share partners this month.', 'If you bill clients the full amount and pay partners a share, this is the gap between your gross and your real revenue.', '[{"label": "Total paid to partners", "type": "amount"}, {"label": "Partners paid", "type": "number"}]'::jsonb, 'Partner statements or your own working of what''s owed under each revenue-share agreement.', 'Matches the agreements on file. Shown separately so both gross and net revenue are on the dashboard.', 'Revenue on the dashboard can''t be shown net of partner share.'),
 ('gw', 'Payment gateway settlement report', 'The payment gateway''s report of what it collected for you, what it kept as fees, and what it sent to your bank.', 'Gateway fees quietly eat into revenue, and settlements arrive days later. This makes both visible.', '[{"label": "Collected through the gateway", "type": "amount"}, {"label": "Gateway fees", "type": "amount"}, {"label": "Settled to bank", "type": "amount"}]'::jsonb, 'Razorpay dashboard → Reports → Settlements → the month → download.', 'What the gateway collected, minus fees, equals what reached the bank.', 'Gateway fees and receipts stay unchecked.'),
 ('adv', 'Advances received', 'Money customers paid before the work was delivered.', 'An advance is not revenue yet — it''s owed back as work. Counting it as revenue overstates the month.', '[{"label": "Advances received", "type": "amount"}, {"label": "Adjusted against invoices", "type": "amount"}]'::jsonb, 'From the bank statement and your billing tool.', 'Advances are not counted as revenue until the work is done.', 'Revenue may be overstated.'),
 ('hold', 'Investment statement', 'The statement for an investment the company holds — a fixed deposit, a fund, or shares.', 'It''s part of your cash cushion. Interest and gains are income and need to be in the books.', '[{"label": "Value at month end", "type": "amount"}, {"label": "Interest or gain this month", "type": "amount"}]'::jsonb, 'Bank or fund house statement for the month.', 'Value and interest are in the books.', 'Interest income may be missed.'),
 ('tb', 'Trial balance', 'A list of every account in the books with its balance at month end. It''s the raw list every other report is built from.', 'If debits and credits don''t match, something is mis-posted — and nothing built on it can be trusted. It''s the first thing we check.', '[{"label": "Total debits", "type": "amount"}, {"label": "Total credits", "type": "amount"}, {"label": "Accounts in the books", "type": "number"}]'::jsonb, 'Tally → Display → Trial balance → month end → export.', 'Debits equal credits. Every account looks sensible against last month.', 'The books can''t be closed for the month.'),
 ('pl', 'Profit and loss', 'The month''s income minus its expenses — whether the company made or lost money on paper.', 'It''s the headline of the month. It differs from cash (bills raised but not collected count here), which is why we show both.', '[{"label": "Revenue", "type": "amount"}, {"label": "Expenses", "type": "amount"}, {"label": "Profit / (loss)", "type": "amount"}]'::jsonb, 'Tally → Display → Profit and loss → the month.', 'Revenue matches the sales register; expenses match the bills and payroll.', 'Profit and loss on the dashboard can''t be updated.'),
 ('bs', 'Balance sheet', 'What the company owns and owes on the last day of the month.', 'It shows whether the company can pay what it owes — cash, receivables and payables, side by side.', '[{"label": "Total assets", "type": "amount"}, {"label": "Total liabilities", "type": "amount"}, {"label": "Cash and bank", "type": "amount"}]'::jsonb, 'Tally → Display → Balance sheet → month end.', 'Cash matches the bank statements; what''s owed matches the ageing reports.', 'Cash and dues can''t be confirmed.'),
 ('pur', 'Purchase register and 2B match', 'Every bill the company received this month, matched against what suppliers reported to GST (GSTR-2B).', 'You can only claim GST credit on bills your suppliers have reported. A mismatch is credit you may lose.', '[{"label": "Purchases", "type": "amount"}, {"label": "Input credit claimed", "type": "amount"}, {"label": "Not yet in GSTR-2B", "type": "amount"}]'::jsonb, 'Tally purchase register, matched against GSTR-2B downloaded from the GST portal.', 'Every bill you claim credit on appears in GSTR-2B.', 'GST credit may be claimed wrongly or missed.'),
 ('gstw', 'GST working', 'The calculation of how much GST is owed for the month: GST charged on sales, less GST credit on purchases.', 'It''s what the GSTR-3B is filed from. Getting it right avoids interest, notices and lost credit.', '[{"label": "GST on sales", "type": "amount"}, {"label": "Input credit", "type": "amount"}, {"label": "Net GST payable", "type": "amount"}]'::jsonb, 'Prepared by the accountant from the sales register and GSTR-2B.', 'GST on sales ties to GSTR-1; credit ties to GSTR-2B; the net is what the GSTR-3B pays.', 'GSTR-3B (due the 20th) can''t be filed on time.'),
 ('mis', 'MIS workbook', 'The month''s management report — P&L, balance sheet, cash, customers — in our fixed format.', 'This is where your dashboard numbers come from. The portal reads 24 figures straight out of it, so no one retypes anything.', '[{"label": "(read from the workbook — none typed)", "type": "text"}]'::jsonb, 'Prepared by the accountant in Prime Bottomline''s fixed template, from the closed books.', 'The portal reads 24 figures and runs 5 checks. Prime Bottomline then compares the month with the last one before publishing.', 'The month can''t be published, so the dashboard keeps showing last month.'),
 ('g1', 'GSTR-1', 'The GST return that lists every sale invoice you raised in the period.', 'Your customers can only claim GST credit once you file it — late filing delays their credit and hurts the relationship. Late fees apply too.', '[{"label": "ARN", "type": "text"}, {"label": "Filed on", "type": "date"}, {"label": "Invoice value reported", "type": "amount"}]'::jsonb, 'GST portal (gst.gov.in) → Services → Returns → Returns dashboard → pick the period → GSTR-1 → view and download the filed return. The ARN is on the acknowledgement.', 'Invoice values match the sales register. Filed by the 11th.', '₹50 a day late fee (₹20 if nil), and your clients can''t claim their GST credit until you file.'),
 ('g3', 'GSTR-3B', 'The monthly GST summary return where the tax is actually paid.', 'It''s the return that moves money. Late payment costs 18% a year in interest, and missed returns block your e-way bills and refunds.', '[{"label": "Tax paid", "type": "amount"}, {"label": "Challan (CPIN)", "type": "text"}, {"label": "ARN", "type": "text"}, {"label": "Filed on", "type": "date"}]'::jsonb, 'GST portal (gst.gov.in) → Services → Returns → Returns dashboard → pick the period → GSTR-3B → download the filed return. The challan (CPIN) comes from Services → Payments.', 'Tax on sales matches GSTR-1, credit matches GSTR-2B, and cash paid matches the challan and the bank statement.', '18% a year interest on the cash part, plus ₹50 a day late fee. Credit and e-way bills can get blocked.'),
 ('gpay', 'GST payment (PMT-06 / CMP-08)', 'GST paid for the month (or quarter) under the QRMP or composition scheme.', 'Even when the return is quarterly, the tax is due monthly. Missing it brings interest.', '[{"label": "Tax paid", "type": "amount"}, {"label": "Challan (CPIN)", "type": "text"}, {"label": "Paid on", "type": "date"}]'::jsonb, 'GST portal → Services → Payments → Create challan (PMT-06) → download the paid challan.', 'Amount matches the month''s GST working.', '18% a year interest.'),
 ('tdsp', 'TDS payment', 'Tax the company deducted from salaries and vendor payments, paid to the government.', 'The money isn''t yours — it''s held for the government. Late deposit costs 1.5% a month and is a red flag in due diligence.', '[{"label": "Amount paid", "type": "amount"}, {"label": "Challan number", "type": "text"}, {"label": "Paid on", "type": "date"}]'::jsonb, 'Income tax portal (incometax.gov.in) → e-Pay Tax → Challan 281 → download the paid challan with its CIN.', 'Amount matches the TDS cut on salaries, vendors and rent in the books, by section.', '1.5% a month interest from the date the tax was cut. A red flag in due diligence.'),
 ('tdsr', 'TDS return', 'The quarterly statement telling the tax department whose tax you deducted and how much.', 'Employees and vendors can only see their tax credit after you file it. Late filing costs ₹200 a day.', '[{"label": "Acknowledgement number", "type": "text"}, {"label": "Filed on", "type": "date"}]'::jsonb, 'Filed on the TRACES / income tax portal using the quarter''s TDS data. The acknowledgement has a token number.', 'Every challan for the quarter is included, against the right people.', '₹200 a day late fee, and staff and vendors can''t see their tax credit.'),
 ('pf', 'PF / ESI payment', 'Provident fund or ESI contributions for employees, paid with the monthly return.', 'It''s employee money held in trust. Delays bring damages and interest and are taken seriously.', '[{"label": "Amount paid", "type": "amount"}, {"label": "Challan / TRRN", "type": "text"}, {"label": "Paid on", "type": "date"}]'::jsonb, 'EPFO employer portal → ECR → pay → download the ECR receipt and the TRRN challan.', 'Matches the payroll register for the month.', 'Interest and damages; taken seriously by EPFO.'),
 ('coi', 'Certificate of incorporation', 'The government''s certificate that the company exists, with its name, number (CIN) and date.', 'Every bank, investor and government form asks for it. It''s the first page of any data room.', '[{"label": "CIN", "type": "text"}, {"label": "Date of incorporation", "type": "date"}]'::jsonb, '', '', ''),
 ('moa', 'MOA and AOA', 'The company''s founding rules: what it can do (MOA), and how it''s run and who decides what (AOA).', 'Investor rights, share classes and board powers live in the AOA. Every round usually changes it.', '[{"label": "Version date", "type": "date"}, {"label": "What changed", "type": "text"}]'::jsonb, '', '', ''),
 ('pan', 'Company PAN', 'The company''s income tax identity number.', 'Needed for every bank account, tax filing and investor KYC.', '[{"label": "PAN", "type": "text"}]'::jsonb, '', '', ''),
 ('tan', 'TAN', 'The number the company uses when it deducts tax from salaries and vendor payments.', 'Without it, TDS can''t be paid or filed.', '[{"label": "TAN", "type": "text"}]'::jsonb, '', '', ''),
 ('gstc', 'GST registration certificate', 'The certificate showing a GST number and the address it''s registered at.', 'Customers ask for it before paying invoices, and it proves where you are registered to sell.', '[{"label": "GSTIN", "type": "text"}, {"label": "Registered on", "type": "date"}]'::jsonb, '', '', ''),
 ('cap', 'Cap table', 'Who owns what share of the company, including options and anything that converts into shares later.', 'It''s the first thing an investor asks for. Errors here are expensive to fix after a round.', '[{"label": "Founders hold", "type": "percent"}, {"label": "Investors hold", "type": "percent"}, {"label": "Option pool", "type": "percent"}]'::jsonb, '', '', ''),
 ('afs', 'Audited financial statements', 'The year''s accounts, checked and signed by the statutory auditor.', 'Banks, investors and the tax department all start from these. Our opening numbers do too.', '[{"label": "Revenue for the year", "type": "amount"}, {"label": "Profit / (loss)", "type": "amount"}, {"label": "Signed on", "type": "date"}]'::jsonb, '', '', ''),
 ('otb', 'Opening trial balance', 'Every account''s balance on 1 April — the starting point for this year''s books.', 'If the starting point is wrong, every month after it is wrong too.', '[{"label": "Total debits", "type": "amount"}, {"label": "Total credits", "type": "amount"}]'::jsonb, '', '', ''),
 ('cl', 'Client list', 'Every client, what they''re billed, how often, and since when.', 'It''s how we know what revenue to expect each month, and spot when a client goes quiet.', '[{"label": "Active clients", "type": "number"}, {"label": "Expected monthly billing", "type": "amount"}]'::jsonb, '', '', ''),
 ('rsa', 'Revenue-share agreements', 'Agreements where the company shares revenue with a partner or pays commission.', 'They decide whether your real revenue is the full invoice or only your share.', '[{"label": "Agreements", "type": "number"}, {"label": "Typical share paid", "type": "percent"}]'::jsonb, '', '', ''),
 ('head', 'Headcount list', 'Everyone working in the company — role, start date, employee or contractor.', 'It decides PF, ESI and professional tax, and is the base for any hiring plan.', '[{"label": "Employees", "type": "number"}, {"label": "Contractors", "type": "number"}]'::jsonb, '', '', ''),
 ('dcert', 'Debenture certificates', 'Certificates issued to each debenture holder showing what they hold.', 'Proof of the debt. Lenders and auditors ask for them, and they must be issued within six months of allotment.', '[{"label": "Certificates issued", "type": "number"}, {"label": "Issued on", "type": "date"}]'::jsonb, '', '', ''),
 ('ts', 'Term sheet', 'The short, mostly non-binding summary of a deal''s key terms before the full agreements.', 'Valuation, board seats and investor rights are agreed here. Everything later follows it.', '[{"label": "Pre-money valuation", "type": "amount"}, {"label": "Amount", "type": "amount"}]'::jsonb, '', '', ''),
 ('sha', 'SSA / SHA', 'The binding agreements under which investors bought shares, and how shareholders deal with each other.', 'They set what investors can block, what you must report to them, and what happens in a sale.', '[{"label": "Signed on", "type": "date"}, {"label": "Parties", "type": "text"}]'::jsonb, '', '', ''),
 ('pas3', 'PAS-3 return of allotment', 'The filing that tells the Registrar of Companies new shares or debentures were issued.', 'Until it''s filed, the allotment isn''t on record. It''s due within 15 days and is checked in every due diligence.', '[{"label": "SRN", "type": "text"}, {"label": "Filed on", "type": "date"}]'::jsonb, '', '', ''),
 ('mgt14', 'MGT-14', 'The filing of important shareholder or board decisions with the Registrar of Companies.', 'Some decisions — like issuing shares or borrowing beyond limits — are only valid once filed. Due within 30 days.', '[{"label": "SRN", "type": "text"}, {"label": "Filed on", "type": "date"}]'::jsonb, '', '', ''),
 ('chg4', 'CHG-4 satisfaction of charge', 'The filing that records a loan has been repaid and the security released.', 'Until it''s filed, the company''s assets still show as pledged — which can block new loans.', '[{"label": "SRN", "type": "text"}, {"label": "Filed on", "type": "date"}]'::jsonb, '', '', ''),
 ('chg', 'Charge registration (CHG-1 / CHG-9)', 'The filing that records the security given for a loan or debentures.', 'Lenders need it registered to be protected. Due within 30 days of creating the charge.', '[{"label": "SRN", "type": "text"}, {"label": "Amount secured", "type": "amount"}]'::jsonb, '', '', ''),
 ('red', 'Debenture redemption proof', 'Proof that debenture holders were repaid.', 'Closes the debt on record and is needed before the charge can be released.', '[{"label": "Amount repaid", "type": "amount"}, {"label": "Repaid on", "type": "date"}]'::jsonb, '', '', ''),
 ('br', 'Board resolution', 'A decision formally taken by the company''s board, signed and certified.', 'Banks, the Registrar and investors ask for it to prove the decision was properly made.', '[{"label": "Passed on", "type": "date"}]'::jsonb, '', '', ''),
 ('generic', 'Anything else', 'A record kept as proof of this event.', 'It''s what a lawyer, auditor or investor will ask to see in due diligence.', '[{"label": "Date", "type": "date"}, {"label": "Reference number", "type": "text"}]'::jsonb, '', '', '')
